import type { Board } from './boardCode.ts';

export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
type Closed = { readonly kind: typeof SELECTION_KINDS.closed };
type One = { readonly kind: typeof SELECTION_KINDS.one; readonly index: number };
type Mismatch = {
  readonly kind: typeof SELECTION_KINDS.mismatch;
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
};
export type Selection = Closed | One | Mismatch;

export interface GameState {
  readonly board: Board;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;
export const MISMATCH_MS = 800;

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}
import { isWon, MAX_MOVES, MISMATCH_MS } from './state.ts';
import type { GameState } from './state.ts';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length ||
      state.matched.includes(index) || isWon(state)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case 'closed':
      return { ...state, started: true, selection: { kind: 'one', index } };
    case 'one': {
      if (selection.index === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.deck[selection.index] === state.deck[index]) {
        return { ...state, moves, matched: [...state.matched, selection.index, index], selection: { kind: 'closed' } };
      }
      return { ...state, moves, selection: { kind: 'mismatch', first: selection.index, second: index, remainingMs: MISMATCH_MS } };
    }
    case 'mismatch':
      return state;
  }
}
import { isWon, MAX_ELAPSED_MS } from './state.ts';
import type { GameState, Selection } from './state.ts';

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  let selection: Selection = state.selection;
  switch (selection.kind) {
    case 'closed':
    case 'one':
      break;
    case 'mismatch':
      selection = milliseconds >= selection.remainingMs
        ? { kind: 'closed' }
        : { ...selection, remainingMs: selection.remainingMs - milliseconds };
      break;
  }
  return { ...state, elapsedMs, selection };
}
export const SUPPORTED_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type GridSize = (typeof SUPPORTED_SIZES)[number];
export const MAX_SEED = 2147483646;
export const BOARD_VERSION = 'np1';

export interface Board {
  readonly code: string;
  readonly size: GridSize;
  readonly seed: number;
}

export function isGridSize(value: unknown): value is GridSize {
  return SUPPORTED_SIZES.some(size => size === value);
}

export function parseBoardCode(code: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
import type { Board } from './boardCode.ts';

const MODULUS = 2147483647;
const MULTIPLIER = 16807;
const GENERATOR_VALUES = MODULUS - 1;

export function nextRandomState(state: number): number {
  // The greatest product is below Number.MAX_SAFE_INTEGER, so this is exact.
  return (state * MULTIPLIER) % MODULUS;
}

export function generateDeck(board: Board): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, i) => Math.floor(i / 2));
  let state = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const possibilities = index + 1;
    const limit = Math.floor(GENERATOR_VALUES / possibilities) * possibilities;
    let draw: number;
    do {
      state = nextRandomState(state);
      draw = state - 1;
    } while (draw >= limit);
    const other = draw % possibilities;
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace === undefined || otherFace === undefined) throw new Error('Invalid deck position.');
    deck[index] = otherFace;
    deck[other] = currentFace;
  }
  return Object.freeze(deck);
}

