      typeof value.boardCode !== 'string' || typeof value.started !== 'boolean' ||
      !isNonnegativeInteger(value.moves) || value.moves > MAX_MOVES ||
      !isNonnegativeInteger(value.elapsedMs) || value.elapsedMs > MAX_ELAPSED_MS) return null;
