  for (const action of value.actions) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index']) ||
        !isNonnegativeInteger(action.atMs) || action.atMs < previousTime ||
        !isPosition(action.index, state.deck.length)) return null;
