import { isGridSize, SUPPORTED_SIZES } from '../boardCode.ts';
import type { GridSize } from '../boardCode.ts';
import { isRecord } from '../jsonInput.ts';
import { MAX_MOVES } from '../state.ts';

export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export interface Preferences {
  readonly size: GridSize;
  readonly best: Readonly<Partial<Record<GridSize, number>>>;
}
export interface PreferenceStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}
export type StorageProvider = () => PreferenceStorage;

export function readPreferences(storage: StorageProvider): Preferences {
  const fallback: Preferences = { size: 4, best: {} };
  try {
    const text = storage().getItem(PREFERENCES_KEY);
    if (text === null) return fallback;
    const value: unknown = JSON.parse(text);
    if (!isRecord(value)) return fallback;
    const best: Partial<Record<GridSize, number>> = {};
    if (isRecord(value.best)) {
      for (const size of SUPPORTED_SIZES) {
        const score = value.best[String(size)];
        if (typeof score === 'number' && Number.isInteger(score) && score >= 0 && score <= MAX_MOVES) {
          best[size] = score;
        }
      }
    }
    return { size: isGridSize(value.size) ? value.size : 4, best };
  } catch {
    return fallback;
  }
}

export function writePreferences(storage: StorageProvider, preferences: Preferences): void {
  try { storage().setItem(PREFERENCES_KEY, JSON.stringify(preferences)); } catch { /* Play continues in memory. */ }
}

export function keepBest(preferences: Preferences, size: GridSize, moves: number): Preferences {
  const current = preferences.best[size];
  if (current !== undefined && current <= moves) return preferences;
  return { ...preferences, best: { ...preferences.best, [size]: moves } };
}
import { MAX_SEED } from '../boardCode.ts';
import type { GridSize } from '../boardCode.ts';
import { createGame } from '../createGame.ts';
import type { GameState } from '../state.ts';

export function freshGame(size: GridSize, previousSeed?: number): GameState {
  const random = new Uint32Array(1);
  crypto.getRandomValues(random);
  const draw = random[0];
  if (draw === undefined) throw new Error('Unable to create a deal.');
  const candidate = (draw % MAX_SEED) + 1;
  const seed = candidate === previousSeed ? (candidate % MAX_SEED) + 1 : candidate;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create a deal.');
  return game;
}
import { formatTime } from '../formatTime.ts';
import { isWon, pairCount } from '../state.ts';
import type { GameState } from '../state.ts';

export interface Announcement {
  readonly id: number;
  readonly text: string;
}

export function turnAnnouncement(before: GameState, after: GameState): string | null {
  if (before.selection.kind !== 'one' || after === before || after.selection.kind === 'one') return null;
  if (after.selection.kind === 'mismatch') return 'No match. Cards close after a short pause.';
  if (isWon(after)) return `Pair found. All pairs found in ${after.moves} moves and ${formatTime(after.elapsedMs)}.`;
  const pairs = pairCount(after);
  return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
}

import { useCallback, useRef, useState } from 'react';
import { activateCard } from '../activateCard.ts';
import { isGridSize } from '../boardCode.ts';
import { createGame } from '../createGame.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { freshGame } from './freshGame.ts';
import { keepBest, readPreferences, writePreferences } from './storage.ts';
import type { Preferences } from './storage.ts';
import { turnAnnouncement } from './turnAnnouncement.ts';
import type { Announcement } from './turnAnnouncement.ts';
import { useActiveClock } from './useActiveClock.ts';

interface SessionView {
  readonly game: GameState;
  readonly preferences: Preferences;
  readonly dealId: number;
  readonly paused: boolean;
  readonly celebrate: boolean;
  readonly announcement: Announcement;
  readonly loadStatus: string;
}

const browserStorage = () => window.localStorage;

function initialSession(): SessionView {
  const preferences = readPreferences(browserStorage);
  return {
    game: freshGame(preferences.size), preferences, dealId: 0, paused: false,
    celebrate: false, announcement: { id: 0, text: '' }, loadStatus: '',
  };
}

export function useGameSession() {
  const [view, setView] = useState(initialSession);
  const game = useRef(view.game);
  const preferences = useRef(view.preferences);
  const paused = useRef(false);
  const generation = useRef(0);
  const announcementId = useRef(0);

  const publish = useCallback((next: GameState) => {
    setView(current => ({ ...current, game: next }));
  }, []);
  const clock = useActiveClock({ game, paused, generation, publish });

  const announce = (text: string) => {
    announcementId.current += 1;
    const announcement = { id: announcementId.current, text };
    setView(current => ({ ...current, announcement }));
  };

  const save = (next: Preferences) => {
    preferences.current = next;
    writePreferences(browserStorage, next);
    setView(current => ({ ...current, preferences: next }));
  };

  const replace = (next: GameState, isPaused: boolean, status = '') => {
    game.current = next;
    paused.current = isPaused;
    generation.current += 1;
    save({ ...preferences.current, size: next.board.size });
    setView(current => ({
      ...current, game: next, dealId: generation.current, paused: isPaused,
      celebrate: false, loadStatus: status,
    }));
    announce(status);
    clock.reset();
  };

  const activate = (index: number) => {
    const before = clock.sample();
    if (paused.current || document.hidden) return;
    const after = activateCard(before, index);
    if (after === before) return;
    game.current = after;
    publish(after);
    const result = turnAnnouncement(before, after);
    if (result !== null) announce(result);
    if (!isWon(before) && isWon(after)) {
      save(keepBest(preferences.current, after.board.size, after.moves));
      setView(current => ({ ...current, celebrate: true }));
    }
    clock.schedule();
  };

  const newGame = () => replace(freshGame(game.current.board.size, game.current.board.seed), false);
  const restart = () => {
    const next = createGame(game.current.board.code);
    if (next) replace(next, false);
  };
  const changeSize = (value: unknown) => {
    if (isGridSize(value) && value !== game.current.board.size) {
      replace(freshGame(value, game.current.board.seed), false);
    }
  };
  const loadBoard = (text: string): boolean => {
    const next = createGame(text.trim());
    if (!next) {
      setView(current => ({ ...current, loadStatus: 'Invalid board code.' }));
      announce('Invalid board code.');
      return false;
    }
    replace(next, false, 'Loaded board.');
    return true;
  };
  const loadSnapshot = (text: string): boolean => {
    const next = decodeSnapshot(text);
    if (!next) {
      setView(current => ({ ...current, loadStatus: 'Invalid snapshot.' }));
      announce('Invalid snapshot.');
      return false;
    }
    const completed = isWon(next);
    replace(next, !completed, completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
    return true;
  };
  const exportSnapshot = () => encodeSnapshot(clock.sample());
  const resume = () => {
    if (!paused.current) return;
    paused.current = false;
    setView(current => ({ ...current, paused: false }));
    clock.reset();
  };

  return {
    game: view.game, dealId: view.dealId, paused: view.paused,
    best: view.preferences.best[view.game.board.size] ?? null,
    celebrate: view.celebrate, announcement: view.announcement, loadStatus: view.loadStatus,
    activate, newGame, restart, changeSize, loadBoard, loadSnapshot, exportSnapshot, resume,
  };
}

export type GameSession = ReturnType<typeof useGameSession>;
import { useCallback, useEffect, useRef } from 'react';
import type { RefObject } from 'react';
import { advanceGame } from '../advanceGame.ts';
import { isWon } from '../state.ts';
import type { GameState } from '../state.ts';

interface ClockOptions {
  readonly game: RefObject<GameState>;
  readonly paused: RefObject<boolean>;
  readonly generation: RefObject<number>;
  readonly publish: (game: GameState) => void;
}

const CLOCK_RENDER_MS = 100;

export function useActiveClock({ game, paused, generation, publish }: ClockOptions) {
  const last = useRef(0);
  const shown = useRef(!document.hidden);
  const alive = useRef(false);
  const timeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const scheduleRef = useRef<() => void>(() => undefined);

  const clear = useCallback(() => {
    if (timeout.current !== null) clearTimeout(timeout.current);
    timeout.current = null;
  }, []);

  const sample = useCallback(() => {
    const now = performance.now();
    const delta = Math.max(0, now - last.current);
    last.current = now;
    if (shown.current && !paused.current) {
      const next = advanceGame(game.current, delta);
      if (next !== game.current) {
        game.current = next;
        publish(next);
      }
    }
    return game.current;
  }, [game, paused, publish]);

  const schedule = useCallback(() => {
    clear();
    if (!alive.current || !shown.current || paused.current || !game.current.started || isWon(game.current)) return;
    const version = generation.current;
    const selection = game.current.selection;
    const delay = selection.kind === 'mismatch' ? Math.min(CLOCK_RENDER_MS, selection.remainingMs) : CLOCK_RENDER_MS;
    timeout.current = setTimeout(() => {
      if (!alive.current || generation.current !== version) return;
      sample();
      scheduleRef.current();
    }, delay);
  }, [clear, game, generation, paused, sample]);
  scheduleRef.current = schedule;

  const reset = useCallback(() => {
    last.current = performance.now();
    schedule();
  }, [schedule]);

  useEffect(() => {
    alive.current = true;
    shown.current = !document.hidden;
    reset();
    const visibilityChanged = () => {
      sample();
      shown.current = !document.hidden;
      reset();
    };
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      alive.current = false;
      clear();
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [clear, reset, sample]);

  return { sample, schedule, reset };
}

import { describe, expect, it } from 'vitest';
import { keepBest, PREFERENCES_KEY, readPreferences, writePreferences } from './storage.ts';
import type { PreferenceStorage, Preferences } from './storage.ts';

function memoryStorage(text: string | null = null) {
  const values = new Map<string, string>([['unrelated', 'keep me']]);
  if (text !== null) values.set(PREFERENCES_KEY, text);
  const storage: PreferenceStorage = {
    getItem: key => values.get(key) ?? null,
    setItem: (key, value) => { values.set(key, value); },
  };
  return { storage, values };
}

describe('saved preferences', () => {
  it('defaults to four columns without a saved game', () => {
    expect(readPreferences(() => memoryStorage().storage)).toEqual({ size: 4, best: {} });
  });

  it.each(['{', 'null', '[]', 'true', '"text"'])('ignores malformed or non-object saved JSON: %s', text => {
    expect(readPreferences(() => memoryStorage(text).storage)).toEqual({ size: 4, best: {} });
  });

  it('accepts supported sizes and validates every score independently', () => {
    const text = JSON.stringify({ size: 16, best: { 4: 8, 6: -1, 8: 1.5, 10: '50', 12: 1000000, 14: 999999, 16: 128, 5: 1 } });
    expect(readPreferences(() => memoryStorage(text).storage)).toEqual({ size: 16, best: { 4: 8, 14: 999999, 16: 128 } });
  });

  it.each([5, '4', null, 4.5])('rejects an unsupported saved size: %s', size => {
    expect(readPreferences(() => memoryStorage(JSON.stringify({ size, best: {} })).storage).size).toBe(4);
  });

  it('rejects non-finite saved scores', () => {
    expect(readPreferences(() => memoryStorage('{"size":4,"best":{"4":1e999}}').storage).best).toEqual({});
  });

  it('catches denied storage access and read failures', () => {
    const denied = () => { throw new Error('denied'); };
    expect(readPreferences(denied)).toEqual({ size: 4, best: {} });
    expect(readPreferences(() => ({ getItem: denied, setItem: () => undefined }))).toEqual({ size: 4, best: {} });
  });

  it('writes only its own key, with no active progress', () => {
    const { storage, values } = memoryStorage();
    const preferences: Preferences = { size: 8, best: { 4: 8 } };
    writePreferences(() => storage, preferences);
    expect(values.get('unrelated')).toBe('keep me');
    expect(values.size).toBe(2);
    expect(JSON.parse(values.get(PREFERENCES_KEY) ?? '')).toEqual(preferences);
  });

  it('catches denied access and failed writes', () => {
    const denied = () => { throw new Error('quota'); };
    const preferences: Preferences = { size: 4, best: {} };
    expect(() => writePreferences(denied, preferences)).not.toThrow();
    expect(() => writePreferences(() => ({ getItem: () => null, setItem: denied }), preferences)).not.toThrow();
  });

  it('keeps a better score in memory and preserves equal or worse records', () => {
    const original: Preferences = { size: 6, best: { 4: 12, 6: 20 } };
    const improved = keepBest(original, 4, 8);
    expect(improved.best).toEqual({ 4: 8, 6: 20 });
    expect(original.best[4]).toBe(12);
    expect(keepBest(improved, 4, 8)).toBe(improved);
    expect(keepBest(improved, 4, 10)).toBe(improved);
    expect(keepBest(improved, 8, 32).best[8]).toBe(32);
  });
});
